#include <iostream>
using namespace std;

int binarySearch(int a[], int n, int target) {
    int l = 0, r = n - 1;
    while (l <= r) {
        int mid = l + (r - l) / 2;
        if (a[mid] == target) return mid;
        else if (a[mid] < target) l = mid + 1;
        else r = mid - 1;
    }
    return -1;
}

int main() {
    int a[] = {1, 3, 5, 7, 9, 11, 13};
    cout << binarySearch(a, 7, 7) << endl;
    return 0;
}

