#include <iostream>
using namespace std;

bool check(int mid) {
    return mid * mid <= 100;
}

int main() {
    int l = 0, r = 100;
    while (l < r) {
        int mid = (l + r + 1) / 2;
        if (check(mid)) l = mid;
        else r = mid - 1;
    }
    cout << l << endl;
    return 0;
}

